"""Audit continuation without replacing historical failed verification receipts."""
from pathlib import Path
p=Path(__file__).with_name('m0_contained_verify.py')
source=p.read_text().replace("lifecycle-corrected/lifecycle.json", "lifecycle-owned/lifecycle.json")
source=source.replace("x['after_reset']", "x['after_enable']")
source=source.replace("bool(life.get('contexts'))", "len(life.get('contexts',[]))==len(life['normal'])==4")
source=source.replace("x['after_restore']==x['prior']", "x['after_restore']==x['prior']==x['window_context'] and x['captured']!=x['prior']")
source=source.replace("'M0':'BLOCKED'", "'M0_prerequisite_slice':'BLOCKED'")
source=source.replace("'M1_started':False", "'M1_started':False,'full_M0_checklist_complete':False")
source=source.replace("['native-corrected','lifecycle-corrected']", "['native-corrected','lifecycle-owned','context-identity']")
source=source.replace("checks['frozen_harnesses_match']=", "snapshots += [('source-context-identity','source-manifest-context-identity.json'),('source-lifecycle-owned','source-manifest-lifecycle-owned.json')]\nchecks['frozen_harnesses_match']=")
source=source.replace("(OUT/'environment.json')", "(OUT/'environment-owned.json')")
source=source.replace("(OUT/'verification.json')", "(OUT/'verification-owned.json')")
source=source.replace("(OUT/'manifest.json')", "(OUT/'manifest-owned.json')")
source=source.replace("p.name!='manifest.json'", "p.name not in ('manifest.json','manifest-owned.json')")
source=source.replace("checks['lifecycle']=", "identity=read('context-identity/identity.json')\nchecks['identity_trace']=identity['status']=='PASS_IDENTITY_TRACE' and identity['gpu_allocations']==0 and identity['context_switches']==0 and all(r['main_thread'] for r in identity['rows']) and len({r['thread'] for r in identity['rows']})==1 and all(r['drw_enabled']==(r['where']=='draw') for r in identity['rows'])\nchecks['lifecycle']=")
exec(compile(source,str(p),'exec'))
